import {parseColumn,parseCSV,fromRows,parseICS,normalize,parseLocalDate} from './core.js';
let pdfLib;
function loadScript(src,globalName){if(window[globalName])return Promise.resolve(window[globalName]);return new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.onload=()=>resolve(window[globalName]);el.onerror=()=>reject(Error('识别组件加载失败，请联网后重试'));document.head.append(el);});}
async function pdf(){if(!Promise.withResolvers)Promise.withResolvers=function(){let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return {promise,resolve,reject};};pdfLib??=await import('./vendor/pdf/pdf.mjs');pdfLib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf/pdf.worker.mjs',import.meta.url).href;return pdfLib;}
function columnsToCourses(columns){let courses=[],unparsed=0;for(let i=0;i<7;i++){const result=parseColumn(columns[i],i+1);courses.push(...result.courses);unparsed+=result.unparsed;}return {courses,rawText:columns.map((text,i)=>`星期${i+1}\n${text}`).join('\n\n'),warnings:['PDF / 图片按七列样本布局解析，请检查星期、节次、周次、教师和教室。',...(unparsed?[`有 ${unparsed} 条节次文本未解析，请查看原文并手动补充。`]:[]),...(courses.length?[]:['没有找到课程，请尝试标准 Excel / CSV 模板，或手动添加课程。'])]};}
function itemLines(items){const sorted=items.filter(i=>i.str?.trim()).sort((a,b)=>Math.abs(a.transform[5]-b.transform[5])>2?b.transform[5]-a.transform[5]:a.transform[4]-b.transform[4]);let rows=[];for(const item of sorted){const y=item.transform[5];let row=rows.find(r=>Math.abs(r.y-y)<2);if(!row){row={y,items:[]};rows.push(row);}row.items.push(item);}return rows.sort((a,b)=>b.y-a.y).map(r=>r.items.sort((a,b)=>a.transform[4]-b.transform[4]).map(i=>i.str).join('')).join('\n');}
async function recognizeImages(canvases,progress){const T=await loadScript('./vendor/ocr/tesseract.min.js','Tesseract');let worker;const columns=Array(7).fill('');try{progress('正在加载中文识别组件，首次使用需要联网…');worker=await T.createWorker('chi_sim+eng',1,{workerPath:new URL('./vendor/ocr/worker.min.js',import.meta.url).href,corePath:new URL('./vendor/ocr/core/',import.meta.url).href,langPath:new URL('./vendor/ocr/lang/',import.meta.url).href,workerBlobURL:false,logger:m=>{if(m.status==='recognizing text')progress(`正在识别，当前列 ${Math.round((m.progress||0)*100)}%`);}});await worker.setParameters({tessedit_pageseg_mode:6,preserve_interword_spaces:0});for(let page=0;page<canvases.length;page++){const canvas=canvases[page];for(let day=0;day<7;day++){progress(`正在识别第 ${page+1}/${canvases.length} 页，星期 ${day+1}…`);const left=.118+day*(.982-.118)/7,width=(.982-.118)/7;const crop=document.createElement('canvas');crop.width=Math.round(canvas.width*width);crop.height=canvas.height;const ctx=crop.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,crop.width,crop.height);ctx.drawImage(canvas,Math.round(canvas.width*left),0,crop.width,canvas.height,0,0,crop.width,canvas.height);const result=await worker.recognize(crop);columns[day]+='\n'+result.data.text.replace(/[ \t]/g,'').replace(/周[.。]/g,'周,');crop.width=1;crop.height=1;}canvas.width=1;canvas.height=1;}return columns;}finally{if(worker)await worker.terminate();}}
async function readPDF(file,progress){const lib=await pdf();const task=lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),cMapUrl:new URL('./vendor/pdf/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/pdf/standard_fonts/',import.meta.url).href,isEvalSupported:false});let doc;try{doc=await task.promise;if(doc.numPages>10)throw Error('请使用最多 10 页的课表 PDF');const columns=Array(7).fill('');for(let i=1;i<=doc.numPages;i++){progress(`正在读取 PDF 第 ${i}/${doc.numPages} 页…`);const page=await doc.getPage(i),content=await page.getTextContent(),viewport=page.getViewport({scale:1}),width=viewport.width;const transformed=content.items.filter(item=>item.transform).map(item=>{const t=lib.Util.transform(viewport.transform,item.transform);t[5]=-t[5];return {...item,transform:t};});for(let d=0;d<7;d++){const left=width*(.118+d*(.982-.118)/7),right=width*(.118+(d+1)*(.982-.118)/7);const items=transformed.filter(item=>item.transform[4]>=left&&item.transform[4]<right);columns[d]+='\n'+itemLines(items);}page.cleanup();}const direct=columnsToCourses(columns);if(direct.courses.length)return direct;
 const ocrColumns=Array(7).fill('');for(let i=1;i<=doc.numPages;i++){progress(`PDF 无可解析文字，正在准备第 ${i} 页图片…`);const page=await doc.getPage(i);const base=page.getViewport({scale:1}),view=page.getViewport({scale:Math.min(3,2200/base.width)});const canvas=document.createElement('canvas');canvas.width=Math.ceil(view.width);canvas.height=Math.ceil(view.height);await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;const cols=await recognizeImages([canvas],progress);for(let d=0;d<7;d++)ocrColumns[d]+='\n'+cols[d];page.cleanup();}return columnsToCourses(ocrColumns);
 }catch(e){if(e.name==='PasswordException')throw Error('PDF 受密码保护，请先保存无密码的课表文件');throw e;}finally{if(doc)await doc.destroy();else await task.destroy();}}
async function imageCanvas(file){const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(3,3000/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas;}finally{URL.revokeObjectURL(url);}}
export async function readFile(file,state,progress){if(file.size>20*1024*1024)throw Error('文件超过 20 MB，请缩小或拆分后再导入');const extension=file.name.split('.').pop().toLowerCase();if(extension==='pdf')return readPDF(file,progress);if(file.type.startsWith('image/')||['png','jpg','jpeg','webp'].includes(extension))return columnsToCourses(await recognizeImages([await imageCanvas(file)],progress));if(['xlsx','xls'].includes(extension)){progress('正在读取 Excel 表格…');const XLSX=await loadScript('./vendor/xlsx.full.min.js','XLSX');const book=XLSX.read(await file.arrayBuffer(),{type:'array'});const rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{header:1,defval:''});return {courses:fromRows(rows),warnings:['读取 Excel 第一张工作表，请校对后导入。'],rawText:rows.map(r=>r.join(' | ')).join('\n')};}const text=await file.text();if(extension==='csv')return {courses:fromRows(parseCSV(text)),warnings:['课程尚未保存，请校对后确认导入。'],rawText:text};if(extension==='ics'){const result=parseICS(text,state);return {...result,rawText:text};}if(extension==='json'){const value=JSON.parse(text.replace(/^\uFEFF/,''));const courses=Array.isArray(value)?value:value.courses;if(!Array.isArray(courses)||courses.length>2000)throw Error('JSON 需要包含课程数组，最多 2000 条');let backup;if(!Array.isArray(value)){if(value.semesterStart&&(!parseLocalDate(value.semesterStart)||parseLocalDate(value.semesterStart).getDay()!==1))throw Error('备份的学期起始日期无效');if(value.periods&&(!Array.isArray(value.periods)||value.periods.length!==12||value.periods.some(p=>!Array.isArray(p)||p.length!==2||p.some(t=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(t))||p[0]>=p[1])))throw Error('备份作息时间无效');backup={semesterStart:value.semesterStart,periods:value.periods};}return {courses:courses.map(normalize),backup,warnings:['备份课程将追加到现有课表；若含学期和作息设置，也会恢复。'],rawText:file.name};}throw Error('暂不支持此文件格式，请选择 PDF、图片、Excel、CSV、ICS 或 JSON');}


